//! Icons: 4-bit coverage masks at 12, 16 and 24 px, generated by tools/fortuna-look-icons from outline glyphs drawn with
//! the Glass concept's canvas (apps/lucina-glass). Generic glyphs only, no third-party marks.

pub use crate::icon_gen::*;

/// A square icon: `size` x `size` pixels of 4-bit coverage, two a byte, low nibble first.
#[derive(Debug)]
pub struct Icon {
    pub size: u8,
    pub data: &'static [u8],
}

impl Icon {
    /// Coverage 0..=15 of pixel `i` (row-major).
    pub fn cov(&self, i: u32) -> u8 {
        let b = self.data[(i / 2) as usize];
        if i & 1 == 0 {
            b & 15
        } else {
            b >> 4
        }
    }
}
